.LoadingsTable th { font-weight: 700; }
.LoadingsTable th:first-child { width: 60%; }
.LoadingsTable .line:hover { background: rgb(219, 219, 219); }
.LoadingsTable .id { display: block; margin-bottom: 3px; color: gray; font-size: 12px; }
.LoadingsTable .customer { overflow-wrap: anywhere; }
.LoadingsTable .ramp-tag { display: inline-block; padding: 5px 7px; border-radius: 3px; background: #137cbd; color: white; }
.empty-message { margin: 0; padding: 10px; color: #5c7080; }
.ramp-loadings .empty-message { width: 100%; padding: 5px; color: #182026; }
